content.solution_code:
class PropulsionSystem {
    constructor(efficiency) {
        if (efficiency <= 0) {
            throw new Error("Efficiency must be positive.");
        }
        this.efficiency = efficiency;
    }

    calculateThrust() {
        throw new Error("calculateThrust() must be implemented by subclasses");
    }
}

class WarpDrive extends PropulsionSystem {
    constructor(warpFactor) {
        super(1.5); // Default efficiency for WarpDrive
        if (warpFactor <= 0) {
            throw new Error("Warp factor must be positive.");
        }
        this.warpFactor = warpFactor;
    }

    calculateThrust() {
        return this.warpFactor * 1000 * this.efficiency;
    }
}

class ImpulseEngine extends PropulsionSystem {
    constructor(powerOutput) {
        super(0.8); // Default efficiency for ImpulseEngine
        if (powerOutput <= 0) {
            throw new Error("Power output must be positive.");
        }
        this.powerOutput = powerOutput;
    }

    calculateThrust() {
        return this.powerOutput * 100 * this.efficiency;
    }
}

class Starship {
    constructor(name, propulsionSystem) {
        this.name = name;
        if (!(propulsionSystem instanceof PropulsionSystem)) {
            throw new Error("Starship must have a valid propulsion system.");
        }
        this.propulsionSystem = propulsionSystem;
    }

    fly(distance) {
        if (distance <= 0) {
            return "Flight distance must be positive.";
        }

        const thrust = this.propulsionSystem.calculateThrust();
        if (thrust <= 0) {
            return "Cannot fly: Propulsion system generates no thrust.";
        }

        const travelTime = distance / thrust;
        return `${this.name} is flying ${distance} light-years using ${this.propulsionSystem.constructor.name}, taking approximately ${travelTime.toFixed(2)} units of time.`;
    }
}

